"""Compare existing ASR word timestamps with source-bound captions, offline.

Usage:
  python3 runs/video-course/audit_caption_timing.py \
    --speech-audit runs/video-course/full-speech-audit.json \
    --manifest docs/customer/demo/video/media-manifest.json \
    --output runs/video-course/v2-caption-asr-audit

Creates fresh input snapshots and timing-audit.json. Uncertain matches remain
uncertain. This does not transcribe audio, edit captions, or certify listening.
"""
import argparse
from collections import Counter, defaultdict
from datetime import datetime, timezone
from difflib import SequenceMatcher
import hashlib
import json
import re
from pathlib import Path
import textwrap

ONES = "zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen".split()
TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

def sha(data):
    return hashlib.sha256(data).hexdigest()

def integer(number):
    if number < 20:
        return [ONES[number]]
    if number < 100:
        return [TENS[number // 10]] + ([] if number % 10 == 0 else integer(number % 10))
    for power, name in [(1000000000, "billion"), (1000000, "million"), (1000, "thousand"), (100, "hundred")]:
        if number >= power:
            return integer(number // power) + [name] + ([] if number % power == 0 else integer(number % power))

def expand_number(raw):
    if "," in raw:
        if re.fullmatch(r"\d{1,3}(,\d{3})+(\.\d+)?", raw):
            raw = raw.replace(",", "")
        else:
            return [token for part in raw.split(",") if part for token in expand_number(part)]
    if "." in raw:
        whole, fraction = raw.split(".", 1)
        return integer(int(whole)) + ["point"] + [ONES[int(digit)] for digit in fraction]
    return integer(int(raw))

def normalize(items):
    tokens = []
    for item in items:
        for raw in re.findall(r"[A-Za-z]+(?:['’][A-Za-z]+)?|\d+(?:[,.]\d+)*|%", item["text"]):
            values = expand_number(raw) if raw[0].isdigit() else ["percent"] if raw == "%" else [raw.lower().replace("’", "'")]
            tokens.extend({**item, "value": value, "single_upper": len(raw) == 1 and raw.isupper()} for value in values)
    merged, index = [], 0
    while index < len(tokens):
        group, next_index = [tokens[index]], index + 1
        if tokens[index]["single_upper"]:
            while next_index < len(tokens) and tokens[next_index]["single_upper"] and tokens[next_index].get("cue") == tokens[index].get("cue"):
                group.append(tokens[next_index])
                next_index += 1
        elif next_index < len(tokens) and [tokens[index]["value"], tokens[next_index]["value"]] in [["net", "mamba"], ["smart", "nic"]]:
            if tokens[next_index].get("cue") == tokens[index].get("cue"):
                group.append(tokens[next_index])
                next_index += 1
        item = {**group[0], "value": "".join(token["value"] for token in group) if len(group) > 1 else group[0]["value"]}
        item["word_ids"] = sorted({word for token in group for word in token["word_ids"]})
        if "start" in item:
            item.update(start=min(t["start"] for t in group), end=max(t["end"] for t in group), probability=min(t["probability"] for t in group))
        merged.append(item)
        index = next_index if len(group) > 1 else index + 1
    return merged

def classify(cue):
    cue["untrusted_boundaries"] = [side for side in ("start", "end") if not cue[side + "_boundary"]["reliable"]]
    deltas = [abs(cue[side + "_boundary"]["caption_minus_asr_seconds"]) for side in ("start", "end") if cue[side + "_boundary"]["reliable"]]
    cue["max_reliable_boundary_abs_delta_seconds"] = max(deltas) if deltas else None
    cue["has_reliable_boundary_over_0_5s"] = any(d > 0.5 for d in deltas)
    cue["has_reliable_boundary_over_1s"] = any(d > 1 for d in deltas)
    if cue["untrusted_boundaries"] or cue["unmatched_expected_tokens"] or cue["unmatched_asr_tokens_inside_matched_cue_span"]:
        cue["status"] = "uncertain_alignment"
    elif cue["has_reliable_boundary_over_0_5s"]:
        cue["status"] = "asr_supported_timing_discrepancy"
    else:
        cue["status"] = "within_0_5s_on_asr_reference"

def audit(speech, manifest):
    if speech["mp4_sha256"] != manifest["artifacts"]["NetMambaPlus-30-minute-course.mp4"]["sha256"] or speech["source_sha256"] != manifest["source_sha256"]:
        raise ValueError("ASR and manifest identities differ")
    scenes = manifest["scenes"]
    asr = {scene["scene"]: scene for scene in speech["scenes"]}
    voiced_ids = {scene["id"] for scene in scenes if scene["narration"]}
    if set(asr) != voiced_ids or len(asr) != len(speech["scenes"]):
        raise ValueError("ASR does not cover exactly every voiced scene")
    chapter_starts = {chapter["start"] for chapter in manifest["chapters"]}
    resume_ids = {scenes[i + 1]["id"] for i, scene in enumerate(scenes[:-1]) if scene["kind"] == "pause"}
    groups = defaultdict(list)
    for index, cue in enumerate(manifest["caption_cues"]):
        groups[cue["scene"]].append((index, cue))
    reports, scene_reports = [], []
    for scene in scenes:
        scene_id, group = scene["id"], groups[scene["id"]]
        if scene["kind"] == "pause":
            reports.extend({"cue_index_zero_based": index, "scene": scene_id, "chapter": scene["chapter"], **cue, "status": "not_assessed_practice_caption"} for index, cue in group)
            continue
        actual = asr[scene_id]
        if actual["expected_narration"] != scene["narration"] or actual["start"] != scene["start"] or actual["end"] != scene["end"]:
            raise ValueError("ASR scene source/timing differs: " + scene_id)
        expected = normalize([{"text": cue["text"], "cue": index, "word_ids": [index]} for index, cue in group])
        recognized = normalize([{"text": word["word"], "word_ids": [index], "start": word["start"], "end": word["end"], "probability": word["probability"]} for index, word in enumerate(actual["words"])])
        expected_values, actual_values = [t["value"] for t in expected], [t["value"] for t in recognized]
        mapping, blocks = {}, {}
        for block in SequenceMatcher(None, expected_values, actual_values, autojunk=False).get_matching_blocks():
            for offset in range(block.size):
                mapping[block.a + offset], blocks[block.a + offset] = block.b + offset, block.size
        expected_counts, actual_counts = Counter(expected_values), Counter(actual_values)
        word_tokens = defaultdict(list)
        for index, token in enumerate(recognized):
            for word in token["word_ids"]:
                word_tokens[word].append(index)
        matched_actual = set(mapping.values())
        unmatched_actual = [{"index": i, "token": t["value"], "start": t["start"], "end": t["end"]} for i, t in enumerate(recognized) if i not in matched_actual]
        scene_reports.append({"scene": scene_id, "chapter": scene["chapter"], "expected_normalized_tokens": len(expected), "asr_normalized_tokens": len(recognized), "matched_tokens": len(mapping), "matched_fraction": len(mapping) / len(expected), "unmatched_expected_tokens": [{"index": i, "token": t["value"], "cue": t["cue"]} for i, t in enumerate(expected) if i not in mapping], "unmatched_asr_tokens": unmatched_actual})
        for position, (index, cue) in enumerate(group):
            indices = [i for i, token in enumerate(expected) if token["cue"] == index]
            report = {"cue_index_zero_based": index, "scene": scene_id, "chapter": scene["chapter"], "chapter_title": scene["chapter_title"], **cue, "normalized_expected_tokens": len(indices), "matched_tokens": sum(i in mapping for i in indices), "unmatched_expected_tokens": [expected[i]["value"] for i in indices if i not in mapping], "special_positions": []}
            if position == 0 and scene["start"] in chapter_starts:
                report["special_positions"].append("chapter_start")
            if position == 0 and scene_id in resume_ids:
                report["special_positions"].append("practice_resume")
            if scene_id == scenes[-1]["id"]:
                report["special_positions"].append("closing_scene")
                if position == len(group) - 1:
                    report["special_positions"].append("course_final_cue")
            for side, ei in [("start", indices[0]), ("end", indices[-1])]:
                boundary = {"expected_token": expected[ei]["value"], "reliable": False}
                if ei not in mapping:
                    boundary["reason"] = "unmatched_expected_boundary"
                else:
                    ai, token = mapping[ei], recognized[mapping[ei]]
                    span = sorted({i for word in token["word_ids"] for i in word_tokens[word]})
                    reasons = []
                    if token["probability"] < 0.8:
                        reasons.append("asr_probability_below_0.8")
                    if ai != (span[0] if side == "start" else span[-1]):
                        reasons.append("boundary_inside_expanded_asr_word")
                    if not (blocks[ei] >= 3 or (len(expected_values[ei]) >= 4 and expected_counts[expected_values[ei]] == actual_counts[actual_values[ai]] == 1)):
                        reasons.append("insufficient_unique_or_three_token_context")
                    if token["end"] <= token["start"]:
                        reasons.append("zero_duration_asr_word")
                    wi = min(token["word_ids"])
                    word = actual["words"][wi]
                    if side == "start" and wi > 0 and re.search(r"[.!?][\"”’]*$", actual["words"][wi - 1]["word"].strip()) and word["end"] - word["start"] > 0.55 and abs(word["start"] - actual["words"][wi - 1]["end"]) < 0.001:
                        reasons.append("possible_sentence_pause_absorption")
                    boundary.update(asr_token=token["value"], asr_word_ids=token["word_ids"], asr_words=[actual["words"][wi]["word"].strip() for wi in token["word_ids"]], asr_probability=token["probability"], asr_time=token[side], caption_time=cue[side], caption_minus_asr_seconds=round(cue[side] - token[side], 6), matching_block_tokens=blocks[ei], asr_scene_edge=abs(token[side] - scene[side]) < 0.001, reliable=not reasons)
                    if reasons:
                        boundary["reason"] = "; ".join(reasons)
                report[side + "_boundary"] = boundary
            begin, end = report["start_boundary"].get("asr_time"), report["end_boundary"].get("asr_time")
            report["unmatched_asr_tokens_inside_matched_cue_span"] = [token for token in unmatched_actual if token["start"] >= begin - 0.0001 and token["end"] <= end + 0.0001] if begin is not None and end is not None else []
            classify(report)
            reports.append(report)
    reports.sort(key=lambda cue: cue["cue_index_zero_based"])
    voiced = [cue for cue in reports if cue["status"] != "not_assessed_practice_caption"]
    reliable = [cue[side + "_boundary"] for cue in voiced for side in ("start", "end") if cue[side + "_boundary"]["reliable"]]
    chapters = []
    for number, chapter in enumerate(manifest["chapters"], 1):
        cues = [cue for cue in voiced if cue["chapter"] == number]
        strict = [cue for cue in cues if cue["status"] == "asr_supported_timing_discrepancy"]
        chapters.append({"chapter": number, "id": chapter["id"], "title": chapter["title"], "speech_cues": len(cues), "status_counts": dict(Counter(cue["status"] for cue in cues)), "fully_aligned_cues_over_0_5s": [cue["cue_index_zero_based"] for cue in strict], "fully_aligned_cues_over_1s": [cue["cue_index_zero_based"] for cue in strict if cue["has_reliable_boundary_over_1s"]], "any_reliable_boundary_over_0_5s_including_uncertain_cues": [cue["cue_index_zero_based"] for cue in cues if cue["has_reliable_boundary_over_0_5s"]], "any_reliable_boundary_over_1s_including_uncertain_cues": [cue["cue_index_zero_based"] for cue in cues if cue["has_reliable_boundary_over_1s"]]})
    cue_by_index = {cue["cue_index_zero_based"]: cue for cue in reports}
    splits, cursor = [], 0
    for scene in scenes:
        if scene["kind"] == "pause":
            cursor += 1
            continue
        for sentence_index, sentence in enumerate(re.split(r"(?<=[.!?])\s+", scene["narration"].strip())):
            chunks = textwrap.wrap(sentence, width=86, break_long_words=False, break_on_hyphens=False)
            if [cue["text"] for cue in manifest["caption_cues"][cursor:cursor + len(chunks)]] != chunks:
                raise ValueError("Caption sentence wrapping differs: " + scene["id"])
            for j in range(len(chunks) - 1):
                left, right = cue_by_index[cursor + j], cue_by_index[cursor + j + 1]
                lb, rb = left["end_boundary"], right["start_boundary"]
                both = lb["reliable"] and rb["reliable"]
                gap = rb["asr_time"] - lb["asr_time"] if both else None
                paired = both and max(lb["asr_word_ids"]) + 1 == min(rb["asr_word_ids"]) and -0.001 <= gap <= 0.2
                status = "strong_paired_word_anchor" if paired else "one_reliable_boundary_only" if lb["reliable"] != rb["reliable"] else "unresolved_pair"
                desired = rb["asr_time"] if paired else None
                splits.append({"scene": scene["id"], "sentence_index_zero_based": sentence_index, "sentence_text": sentence, "left_cue_index_zero_based": cursor + j, "right_cue_index_zero_based": cursor + j + 1, "left_caption_text": chunks[j], "right_caption_text": chunks[j + 1], "original_caption_boundary_seconds": left["end"], "status": status, "asr_gap_seconds": gap, "desired_boundary_global_seconds": desired, "desired_raw_wav_boundary_seconds": (desired - scene["start"]) * scene["tempo"] if paired else None, "boundary_shift_late_seconds": left["end"] - desired if paired else None})
            cursor += len(chunks)
    special = {}
    for tag in ["chapter_start", "practice_resume", "closing_scene", "course_final_cue"]:
        cues = [cue for cue in voiced if tag in cue["special_positions"]]
        special[tag] = {"cue_count": len(cues), "status_counts": dict(Counter(cue["status"] for cue in cues)), "cue_indices_with_reliable_boundary_over_0_5s": [cue["cue_index_zero_based"] for cue in cues if cue["has_reliable_boundary_over_0_5s"]]}
    return {"status": "supplementary_asr_timing_review_complete", "created_at": datetime.now(timezone.utc).isoformat(), "mp4_sha256": speech["mp4_sha256"], "source_sha256": speech["source_sha256"], "method": {"alignment": "Per-scene monotonic exact normalized-token blocks; SequenceMatcher autojunk=False.", "normalization": "Case/punctuation/hyphens; spoken integer/decimal expansions; valid grouped commas; percent; uppercase spelled acronym joins; Net Mamba and Smart NIC joins. Ambiguous ASR numerals remain unmatched.", "boundary_acceptance": "Exact boundary match, probability >=0.8, positive duration, original-word edge, >=3 matching tokens or unique >=4-letter token. Long sentence-onset words absorbing the preceding pause are uncertain. Any unmatched expected/ASR interior token or untrusted edge makes the cue uncertain.", "signed_delta": "Caption minus ASR time. Positive start = late appearance; positive end = late disappearance.", "limitations": "ASR lexical confidence is not calibrated timing confidence. No human listening or +/-0.5-second human acceptance. New audio must have new hash-matched ASR. Split raw offsets are descriptive only; apply no correction without unchanged sentence and raw-WAV identity guards."}, "summary": {"all_cues": len(reports), "speech_cues": len(voiced), "practice_cues": len(reports) - len(voiced), "voiced_scenes": len(scene_reports), "asr_original_words": sum(len(s["words"]) for s in speech["scenes"]), "status_counts": dict(Counter(cue["status"] for cue in reports)), "reliable_boundaries": len(reliable), "untrusted_boundaries": len(voiced) * 2 - len(reliable), "reliable_boundaries_over_0_5s": sum(abs(b["caption_minus_asr_seconds"]) > 0.5 for b in reliable), "reliable_boundaries_over_1s": sum(abs(b["caption_minus_asr_seconds"]) > 1 for b in reliable), "fully_aligned_cues_over_1s": sum(c["status"] == "asr_supported_timing_discrepancy" and c["has_reliable_boundary_over_1s"] for c in voiced)}, "chapters": chapters, "special_position_summary": special, "special_position_cues": [cue for cue in voiced if cue["special_positions"]], "cues": reports, "scene_alignment": scene_reports, "split_anchor_summary": {"within_sentence_split_count": len(splits), "status_counts": dict(Counter(s["status"] for s in splits)), "strong_splits_over_0_5s": sum(s["status"] == "strong_paired_word_anchor" and abs(s["boundary_shift_late_seconds"]) > 0.5 for s in splits), "strong_splits_over_1s": sum(s["status"] == "strong_paired_word_anchor" and abs(s["boundary_shift_late_seconds"]) > 1 for s in splits)}, "within_sentence_splits": splits, "uncertain_cue_indices_zero_based": [c["cue_index_zero_based"] for c in voiced if c["status"] == "uncertain_alignment"], "fully_aligned_discrepancy_cue_indices_zero_based": [c["cue_index_zero_based"] for c in voiced if c["status"] == "asr_supported_timing_discrepancy"], "recommendation": "Review strong paired-word timing discrepancies in corresponding encoded audio. Preserve uncertain cues explicitly; never auto-pass or auto-fail them. Keep waveform/text identity guards for any correction, and recheck final regenerated media."}

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--speech-audit", type=Path, required=True)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    speech_bytes, manifest_bytes = args.speech_audit.read_bytes(), args.manifest.read_bytes()
    result = audit(json.loads(speech_bytes), json.loads(manifest_bytes))
    args.output.mkdir(parents=True, exist_ok=False)
    snapshots = {}
    for name, data in [("speech-input.json", speech_bytes), ("manifest-input.json", manifest_bytes)]:
        path = args.output / name
        path.write_bytes(data)
        snapshots[name] = {"path": str(path), "sha256": sha(data)}
    result.update(input_snapshots=snapshots, helper_sha256=sha(Path(__file__).read_bytes()))
    target = args.output / "timing-audit.json"
    target.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps({"receipt": str(target), "sha256": sha(target.read_bytes()), "summary": result["summary"], "split_anchor_summary": result["split_anchor_summary"]}, indent=2))

if __name__ == "__main__":
    main()
